import React from 'react';

interface DataTableProps {
  columns: string[];
  rows: unknown[][];
  className?: string;
}

export function DataTable({ columns, rows, className }: DataTableProps) {
  return (
    <div style={{ border: '1px solid {{token:colors.base.border}}', borderRadius: '{{token:spacing.card.borderRadius}}', overflow: 'auto', background: '{{token:colors.base.surface}}' }} className={className}>
      <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '{{token:typography.scale.sm}}' }}>
        <thead>
          <tr style={{ background: '{{token:colors.glass.tint}}' }}>
            {columns.map((c) => (
              <th key={c} style={{ textAlign: 'left', padding: '{{token:spacing.card.gap}}', color: '{{token:colors.text.secondary}}', fontWeight: 600 }}>{c}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((r, i) => (
            <tr key={i} style={{ borderTop: '1px solid {{token:colors.base.border}}', color: '{{token:colors.text.primary}}' }}>
              {r.map((cell, j) => (
                <td key={j} style={{ padding: '{{token:spacing.card.gap}}' }}>{String(cell)}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

